        source: "“《析津志辑佚》”",
        date: "2026-06-12",
        tags: ["元代", "社会生活", "旅行"],
        excerpt: "“延祐三年春，予自大都启行，沿御河南下。四月初至通州，见运河中粮船如织。过直沽，海舶鳞集，商贾云屯。至临清，始见棉花铺遍野。过扬州，市井繁华，不减大都。五月抵杭州，真东南第一州也。”",
        commentary: `
            <p>这段记载出自元代熊梦祥《析津志》，描述了从大都（今北京）沿运河到杭州的旅途见闻。京杭大运河是元代南北大统一的动脉，不仅运输物资，也传递着文化和信息。“棉花铺遍野”的细节透露出元代农业经济的重要变化——棉花的推广种植，这场“衣被天下”的革命，正静悄悄地改变亿万人的生活。</p>
            <p>《析津志》是元末熊梦祥所撰的大都方志，原书久佚，今本系辑佚而成，材料来自《永乐大典》等残存引文。这类行旅记述因此带有拼接痕迹，年月与地名偶有错置，使用时需稍加辨正。但正因它出自方志而非正史，反而保留了不少官方记载不取的日常细节。</p>
            <p>路线本身即是一份制度地图。自大都沿御河南下至通州，是通惠河接通漕运的起点；直沽一带海舶云集，说明河运与海运在此交汇；临清、扬州、杭州三处，分别是会通河、江淮运河与江南运河上的枢纽。延祐三年（1316年）正值漕运制度稳定期，沿线城市的商业规模由此支撑。</p>
            <p>“棉花铺遍野”一句最值得注意。元代棉花种植自岭南、闽广北传，经江南推广至山东、河南，到元中期已进入华北平原。它改变了衣料结构，也改变了农家生计，纺织成为副业收入，赋税中开始出现棉布折纳。作者把这一变化写作路边所见，恰说明棉作在北方已是寻常景象。</p>
        `
