            <p>圆仁于承和五年随最后一批遣唐使出发，四船渡海，途中遇风漂散，他本人在扬州登岸，其后北上巡礼五台山，入长安，又逢会昌灭佛，被迫还俗，最终于大中元年搭新罗商船归国。卷四所记正是灭佛前后的见闻与这段归程，故其笔下的海面既是地理空间，也是政治变局之后的退路。</p>
