            <p>这条材料能说明的，是中原王朝对高句丽的地理认知框架，以及辽东在战略想象中所占的位置。它的局限也很清楚：描述是静态的，不反映疆域伸缩；四至表述以中原为中心，会抹平边界的模糊与浮动；里数往往夸张。若要讨论疆域与城防，还需结合好太王碑、高句丽城址考古，以及《周书》《北史》的平行记载。</p>
