            <p>这是《三国史记·乙支文德传》所记的一首五言四句诗，作于大业八年隋军进逼平壤之际，通常题为《遗于仲文诗》。于仲文是隋军九军之一的主将，与宇文述同掌东征陆军。全诗只二十字，却同时是一份战书与一段外交辞令。</p>
